<script setup>
import { computed, ref } from 'vue'
const tab = ref('position'), position = ref('relative'), direction = ref('row'), justify = ref('space-between'), columns = ref(3), unit = ref('rem'), unitValue = ref(16)
const tabs = [['position','Position'],['flex','Flexbox'],['grid','Grid'],['units','Единицы']]
const positionText = { static:['Обычный поток','Элемент занимает место в структуре и двигает следующие блоки.'], relative:['Смещение от себя','Элемент остаётся в потоке, а его место сохраняется. Ближайшая аналогия — слой в Auto Layout со сдвигом, но это не точное соответствие.'], absolute:['Свободный слой','Элемент выходит из потока и привязывается к позиционированному контейнеру. Это корректная аналогия Ignore auto layout / Absolute position в Figma.'], fixed:['Закреплён у окна','Элемент закреплён относительно окна браузера. В прототипе Figma этому близко Fix position when scrolling.'], sticky:['Поток, затем закрепление','До границы прокрутки элемент в потоке, после — закрепляется внутри scrolling-контейнера. В Figma есть сходное sticky-поведение в прототипах.'] }
const posStyle = computed(() => ({ position: position.value, top: position.value === 'relative' ? '-10px' : ['absolute','fixed','sticky'].includes(position.value) ? '12px' : 'auto', right: ['absolute','fixed'].includes(position.value) ? '12px' : 'auto' }))
const flexStyle = computed(() => ({ display:'flex', flexDirection:direction.value, justifyContent:justify.value, gap:'12px', flexWrap:'wrap', minHeight:'180px' }))
const gridStyle = computed(() => ({ display:'grid', gridTemplateColumns:`repeat(${columns.value}, minmax(0, 1fr))`, gap:'12px' }))
const units = { px:['Фиксированная CSS-точка','Удобна для тонких границ и небольших деталей. CSS `px` не равен физическому пикселю экрана и не имеет прямой аналогии в Figma.'], '%':['Доля родителя','Это отношение к размеру контейнера. Fill container в Figma — другой механизм Auto Layout, поэтому их не стоит отождествлять.'], rem:['От корневого текста','Это модуль, заданный размером текста у `html`. У Figma нет прямого эквивалента; дизайн-токены лишь помогают поддерживать похожую системность.'], em:['От текущего текста','Размер зависит от текущего текстового контекста и может накапливаться во вложенности. Прямого аналога в Figma нет.'], vw:['Доля окна браузера','Размер зависит от viewport, а не от размера фрейма Figma.'], fr:['Доля свободного Grid','Работает только в CSS Grid. Похоже по идее пропорций колонок, но не равно сетке или constraints Figma.'] }
const unitVisual = computed(() => Math.min(100, unit.value === 'px' ? unitValue.value / 3 : unit.value === '%' ? unitValue.value : unit.value === 'vw' ? unitValue.value : unit.value === 'fr' ? unitValue.value * 20 : unitValue.value * 3))
</script>
<template><div class="flex flex-col gap-6"><header><h1 class="text-2xl font-extrabold text-slate-900">Справочник CSS</h1><p class="mt-1 text-slate-500">Меняйте свойства — схема и код обновляются плавно.</p></header><nav class="flex flex-wrap gap-2"><button v-for="item in tabs" :key="item[0]" class="rounded-full px-4 py-2 text-sm font-semibold transition" :class="tab===item[0]?'bg-brand-gradient text-slate-800 shadow-sm':'bg-white text-slate-600 ring-1 ring-slate-200'" @click="tab=item[0]">{{ item[1] }}</button></nav>
<section v-if="tab==='position'" class="flex flex-col gap-4"><div class="card p-5"><div class="flex flex-wrap gap-2"><button v-for="(_, name) in positionText" :key="name" class="rounded-lg px-3 py-2 font-mono text-sm" :class="position===name?'bg-slate-800 text-white':'bg-slate-100 text-slate-600'" @click="position=name">{{ name }}</button></div><div class="relative mt-5 min-h-72 overflow-hidden rounded-xl border border-dashed border-slate-300 bg-slate-50 p-5"><span class="text-xs font-semibold uppercase tracking-wide text-slate-400">Позиционированный контейнер</span><div class="mt-8 flex gap-3"><div class="rounded-lg bg-white p-4 shadow-sm">Сосед A</div><div class="rounded-lg border-2 border-dashed border-slate-300 p-4 text-slate-400">Исходное место</div><div class="rounded-lg bg-white p-4 shadow-sm">Сосед B</div></div><div class="rounded-lg bg-brand-gradient p-4 font-semibold shadow-md transition-all duration-500 ease-out" :style="posStyle">Выбранный блок</div><span v-if="position==='absolute'" class="absolute bottom-3 right-4 text-xs text-slate-400">не занимает место в потоке</span><span v-if="position==='fixed'" class="absolute bottom-3 right-4 text-xs text-slate-400">привязан к viewport</span><span v-if="position==='sticky'" class="absolute bottom-3 right-4 text-xs text-slate-400">нужен scroll + top</span></div></div><div class="card p-5"><h2 class="font-bold">{{ positionText[position][0] }}</h2><p class="mt-2 text-slate-600">{{ positionText[position][1] }}</p><pre class="mt-4 rounded-xl bg-slate-950 p-4 text-sm text-slate-200"><code>position: {{ position }};
top: {{ position === 'static' ? 'не применяется' : '12px' }};</code></pre></div></section>
<section v-else-if="tab==='flex'" class="flex flex-col gap-4"><div class="card p-5"><div class="flex flex-wrap gap-3"><label>Направление <select v-model="direction" class="ml-2 rounded border p-2"><option>row</option><option>column</option></select></label><label>Распределение <select v-model="justify" class="ml-2 rounded border p-2"><option>space-between</option><option>center</option><option>flex-start</option></select></label></div><div class="mt-5 rounded-xl border border-dashed border-slate-300 bg-slate-50 p-5 transition-all duration-500" :style="flexStyle"><div v-for="n in 4" :key="n" class="rounded-xl bg-brand-gradient p-4 text-center font-bold transition-all duration-500">{{ n }}</div></div></div><div class="card p-5 text-slate-600">Flexbox — веб-аналог <strong>Auto Layout</strong>: <code>flex-direction</code> задаёт главную ось, <code>justify-content</code> распределяет элементы по ней.<pre class="mt-4 rounded-xl bg-slate-950 p-4 text-sm text-slate-200"><code>display: flex;
flex-direction: {{ direction }};
justify-content: {{ justify }};</code></pre></div></section>
<section v-else-if="tab==='grid'" class="flex flex-col gap-4"><div class="card p-5"><label>Колонки <input v-model.number="columns" type="range" min="2" max="4" class="ml-2"><span>{{ columns }}</span></label><div class="mt-5 rounded-xl border border-dashed border-slate-300 bg-slate-50 p-5 transition-all duration-500" :style="gridStyle"><div v-for="n in 8" :key="n" class="min-h-20 rounded-xl bg-brand-gradient p-3 font-bold transition-all duration-500">{{ n }}</div></div></div><div class="card p-5 text-slate-600">Grid похож на сетку фрейма Figma: вы управляете рядами и колонками одновременно.<pre class="mt-4 rounded-xl bg-slate-950 p-4 text-sm text-slate-200"><code>display: grid;
grid-template-columns: repeat({{ columns }}, 1fr);</code></pre></div></section>
<section v-else class="flex flex-col gap-4"><div class="card p-5"><div class="flex flex-wrap gap-2"><button v-for="(_, name) in units" :key="name" class="rounded-lg px-3 py-2 font-mono" :class="unit===name?'bg-slate-800 text-white':'bg-slate-100 text-slate-600'" @click="unit=name; unitValue = name==='px'?48:name==='%'?60:name==='fr'?2:16">{{ name }}</button></div><label class="mt-5 block text-sm font-semibold text-slate-600">Значение: <span class="font-mono">{{ unitValue }}{{ unit }}</span><input v-model.number="unitValue" type="range" class="mt-2 w-full" :min="unit==='px'?4:unit==='fr'?1:1" :max="unit==='px'?240:unit==='fr'?5:100"></label><div class="mt-5 rounded-xl border border-dashed border-slate-300 bg-slate-50 p-6"><div v-if="unit==='px'" class="mb-3 flex h-6 items-end overflow-hidden"><span v-for="n in 40" :key="n" class="h-3 w-3 border-l border-slate-400" :class="n % 5 === 0 ? 'h-6' : ''"></span></div><div v-if="unit==='%'" class="mb-3 h-5 w-full rounded bg-slate-200"><div class="h-5 rounded bg-slate-400 transition-all duration-500" :style="{width: `${unitValue}%`}"></div></div><div v-if="unit==='rem' || unit==='em'" class="mb-3 font-mono text-slate-500" :style="{fontSize: `${Math.min(28, unitValue)}px`}">M — модуль текста</div><div class="rounded-xl bg-brand-gradient p-5 text-center font-bold transition-all duration-500" :style="{width: `${unitVisual}%`,maxWidth:'100%'}">{{ unitValue }}{{ unit }}</div></div></div><div class="card p-5"><h2 class="font-bold">{{ unit }}</h2><p class="mt-2 text-slate-600">{{ units[unit][0] }}. {{ units[unit][1] }}</p></div></section></div></template>
